window.EDUQUEST_COVER=``;

/* EDUQUEST — Laboratorio de Derivadas. No usa eval(); math.js interpreta expresiones. */
const state={funcs:[{f:'sin(x)',d:'cos(x)'},{f:'x^2-4',d:'2*x'},{f:'exp(0.3*x)',d:'0.3*exp(0.3*x)'}],cover:'',ar:false,stream:null};
const $=id=>document.getElementById(id),$$=s=>[...document.querySelectorAll(s)];
function toast(s){const t=$('toast');t.textContent=s;t.classList.add('show');clearTimeout(t._t);t._t=setTimeout(()=>t.classList.remove('show'),3000)}
function fmt(x,d=5){return Number.isFinite(x)?Number(x.toFixed(d)).toString():'—'}
function nums(s){return s.split(/[\s,;]+/).map(Number).filter(Number.isFinite)}
function rng(a,b,n){const r=[],h=(b-a)/(n-1);for(let i=0;i<n;i++)r.push(a+i*h);return r}
function allowed(expr,vars=['x']){if(!expr||expr.length>150||/[;{}\[\]=]|eval|import|require|load\(/i.test(expr))return false;try{const sy=math.parse(expr).filter(n=>n.isSymbolNode).map(n=>n.name);return sy.every(s=>vars.includes(s)||['sin','cos','tan','asin','acos','atan','sqrt','abs','exp','log','ln','pi','e','pow'].includes(s))}catch{return false}}
function ev(expr,scope){try{return Number(math.parse(expr).evaluate(scope))}catch{return NaN}}
function derivativeNumeric(expr,x,h=1e-5){return(ev(expr,{x:x+h})-ev(expr,{x:x-h}))/(2*h)}
function roots(expr,a,b){const xs=rng(a,b,700),out=[];let px=xs[0],pf=ev(expr,{x:px});for(let i=1;i<xs.length;i++){const x=xs[i],f=ev(expr,{x});if(Number.isFinite(f)&&Number.isFinite(pf)&&pf*f<0){let l=px,r=x,fl=pf;for(let k=0;k<55;k++){let m=(l+r)/2,fm=ev(expr,{x:m});if(fl*fm<=0)r=m;else{l=m;fl=fm}}let z=(l+r)/2;if(!out.length||Math.abs(z-out.at(-1))>.001)out.push(z)}px=x;pf=f}return out}
function nav(v){if(v!=='home'&&!currentStudent){showLogin();return}$$('.view').forEach(x=>x.classList.toggle('active',x.id==='view-'+v));$$('.nav button').forEach(x=>x.classList.toggle('active',x.dataset.view===v));$('pageTitle').textContent={home:'Inicio / ingreso',concept:'Conceptos y reglas',explain:'Explicación de derivadas',lab:'Laboratorio de funciones',exercises:'Ejercicios y banco',geometry:'Representación geométrica',final:'Evaluación final',teacher:'Modo docente'}[v]||'Eduquest';$('sidebar').classList.remove('open');if(v==='geometry')plotGeometry();if(v==='final')renderFinalTest()}
function plotFunctions(){const fs=[1,2,3].map(i=>({f:$('f'+i).value.trim(),d:$('d'+i).value.trim()}));if(fs.some(q=>!allowed(q.f)||!allowed(q.d))){toast('Revisa las expresiones: solo se permiten operaciones y funciones matemáticas seguras.');return}state.funcs=fs;const a=+$('xmin').value,b=+$('xmax').value,n=Math.min(2000,Math.max(50,+$('samples').value||400)),x0=+$('x0').value,x=rng(a,b,n),tr=[];fs.forEach((q,i)=>{const y=x.map(z=>ev(q.f,{x:z})),d=x.map(z=>ev(q.d,{x:z}));tr.push({x,y,mode:'lines',name:'f'+(i+1)+'(x) = '+q.f});tr.push({x,y:d,mode:'lines',name:'f'+(i+1)+'′(x) = '+q.d,line:{dash:'dot'}})});const checks=fs.map(q=>{try{return math.simplify(math.derivative(q.f,'x')).equals(math.simplify(q.d))}catch{return false}});const y0=ev(fs[0].f,{x:x0}),s=ev(fs[0].d,{x:x0});tr.push({x,y:x.map(z=>y0+s*(z-x0)),mode:'lines',name:'Tangente',line:{dash:'dash',color:'#111'}});Plotly.newPlot('functionPlot',tr,{paper_bgcolor:'transparent',plot_bgcolor:'transparent',xaxis:{title:'x'},yaxis:{title:'y'},margin:{l:50,r:20,t:25,b:45},legend:{orientation:'h'}},{responsive:true,displaylogo:false});const rr=roots(fs[0].f,a,b);$('functionInfo').innerHTML=`<div class="metrics"><div class="metric">f₁(x₀)<b>${fmt(y0)}</b></div><div class="metric">f₁′(x₀)<b>${fmt(s)}</b></div><div class="metric">Raíces aprox.<b>${rr.length?rr.map(z=>fmt(z,3)).join(', '):'No detectadas'}</b></div><div class="metric">Comprobación simbólica<b>${checks.map((v,i)=>'f'+(i+1)+': '+(v?'✓':'Revisar')).join(' · ')}</b></div></div>`;const rows=x.slice(0,12).map(z=>`<tr><td>${fmt(z)}</td><td>${fmt(ev(fs[0].f,{x:z}))}</td><td>${fmt(ev(fs[0].d,{x:z}))}</td></tr>`).join('');$('functionRows').innerHTML=rows}
function csv(){const x=rng(+$('xmin').value,+$('xmax').value,Math.min(2000,+$('samples').value||400));const rows=[['x','f1','f1_derivada','f2','f2_derivada','f3','f3_derivada']];x.forEach(z=>rows.push([z,...state.funcs.flatMap(q=>[ev(q.f,{x:z}),ev(q.d,{x:z})])]));const b=new Blob([rows.map(r=>r.join(',')).join('\n')],{type:'text/csv'}),a=document.createElement('a');a.href=URL.createObjectURL(b);a.download='eduquest-funciones.csv';a.click()}
function png(id,name){Plotly.downloadImage(id,{format:'png',filename:name,width:1400,height:850})}
const rules=[['Constante','f(x)=c','f′(x)=0'],['Identidad','f(x)=x','f′(x)=1'],['Lineal','f(x)=mx+b','f′(x)=m'],['Potencia','f(x)=xⁿ','f′(x)=n·xⁿ⁻¹'],['Cuadrática','f(x)=ax²+bx+c','f′(x)=2ax+b'],['Exponencial','f(x)=eˣ','f′(x)=eˣ'],['Base a','f(x)=aˣ','f′(x)=aˣ ln(a)'],['Seno','sin(x)','cos(x)'],['Coseno','cos(x)','−sin(x)'],['Producto','uv','u′v+uv′'],['Cociente','u/v','(u′v−uv′)/v²'],['Cadena','g(h(x))','g′(h(x))h′(x)'],['Máximo/mínimo','f′(x)=0','Puntos críticos'],['Aplicaciones','cambio y optimización','Interpretación de tasas']];
function renderRules(){$('rules').innerHTML=rules.map(r=>`<article class="card rule"><h3>${r[0]}</h3><p class="formula">${r[1]} → ${r[2]}</p><p class="muted">Identifica la estructura antes de aplicar la regla y simplifica al final.</p></article>`).join('')}
const ex=[['Deriva x³−4x+2','3*x^2-4'],['Deriva sin(x)+x²','cos(x)+2*x'],['Deriva exp(0.3*x)','0.3*exp(0.3*x)'],['Deriva (x²+1)(x−3)','2*x*(x-3)+(x^2+1)'],['Deriva (x²+1)/(x−1)','(2*x*(x-1)-(x^2+1))/(x-1)^2'],['Si f=x²−4, calcula f′(2)','4']];
function renderEx(){ $('exList').innerHTML=ex.map((q,i)=>`<article class="exercise"><b>${i+1}. ${q[0]}</b><div class="field"><label>Respuesta</label><input id="ex${i}"></div><div class="actions"><button class="btn" onclick="checkEx(${i})">Comprobar</button><span id="fb${i}"></span></div></article>`).join('')}
function checkEx(i){let ok=false;try{ok=math.simplify($('ex'+i).value).equals(math.simplify(ex[i][1]))}catch{}const f=$('fb'+i);f.className='feedback '+(ok?'ok':'bad');f.textContent=ok?'✓ Correcto':'Revisa la regla y vuelve a intentarlo.'}
function plotGeometry(){const x=rng(-6,6,250),f=state.funcs[0]?.f||'sin(x)';Plotly.newPlot('geometryPlot',[{x,y:x.map(z=>ev(f,{x:z})),name:'f(x)',mode:'lines'},{x,y:x.map(z=>derivativeNumeric(f,z)),name:'f′(x) numérica',mode:'lines'}],{paper_bgcolor:'transparent',plot_bgcolor:'transparent',xaxis:{title:'x'},yaxis:{title:'y'},margin:{l:50,r:20,t:25,b:45}},{responsive:true,displaylogo:false})}
function surface(){const e=$('surfExpr').value.trim(),n=Math.min(80,Math.max(15,+$('surfRes').value||40));if(!allowed(e,['x','y'])){toast('Superficie no válida. Usa x, y y funciones matemáticas permitidas.');return}const xs=rng(-4,4,n),ys=rng(-4,4,n),z=ys.map(y=>xs.map(x=>ev(e,{x,y}))),x0=+$('sx0').value,y0=+$('sy0').value,h=1e-4,z0=ev(e,{x:x0,y:y0}),zx=(ev(e,{x:x0+h,y:y0})-ev(e,{x:x0-h,y:y0}))/(2*h),zy=(ev(e,{x:x0,y:y0+h})-ev(e,{x:x0,y:y0-h}))/(2*h);Plotly.newPlot('surfacePlot',[{type:'surface',x:xs,y:ys,z,colorscale:[[0,'#0877c9'],[.5,'#00C2FF'],[.75,'#B8EF2B'],[1,'#FF7A1A']],contours:{z:{show:true,project:{z:true}}}}],{paper_bgcolor:'transparent',scene:{xaxis:{title:'x'},yaxis:{title:'y'},zaxis:{title:'z'}},margin:{l:0,r:0,t:20,b:0}},{responsive:true,displaylogo:false});$('surfaceInfo').innerHTML=`<div class="metrics"><div class="metric">z(x₀,y₀)<b>${fmt(z0)}</b></div><div class="metric">∂z/∂x<b>${fmt(zx)}</b></div><div class="metric">∂z/∂y<b>${fmt(zy)}</b></div><div class="metric">|∇z|<b>${fmt(Math.hypot(zx,zy))}</b></div></div>`}
function projectSave(){const p={title:$('ptitle').value,level:$('plevel').value,duration:$('pduration').value,objective:$('pobjective').value,challenge:$('pchallenge').value,evidence:$('pevidence').value};localStorage.setItem('eduquestProject',JSON.stringify(p));renderProject(p);toast('Proyecto guardado en localStorage.')}
function renderProject(p){$('script').textContent=`1. OBSERVAR: ${p.title}\n2. CALCULAR: aplicar la regla adecuada.\n3. EXPLICAR: justificar el procedimiento y comprobarlo gráficamente.\n4. TRANSFERIR: resolver una situación nueva.\n\nNivel: ${p.level}\nDuración: ${p.duration}\nObjetivo: ${p.objective}\nPregunta retadora: ${p.challenge}\nEvidencia: ${p.evidence}`}
function exportProject(){const p=JSON.parse(localStorage.getItem('eduquestProject')||'null');if(!p)return toast('Guarda primero el proyecto.');const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([JSON.stringify(p,null,2)],{type:'application/json'}));a.download='eduquest-proyecto.json';a.click()}
function importProject(file){const r=new FileReader();r.onload=()=>{try{const p=JSON.parse(r.result);[['ptitle','title'],['plevel','level'],['pduration','duration'],['pobjective','objective'],['pchallenge','challenge'],['pevidence','evidence']].forEach(([a,b])=>$(a).value=p[b]||'');renderProject(p);toast('Proyecto importado.')}catch{toast('JSON inválido.')}};r.readAsText(file)}
function assess(){const n=$('student').value.trim(),s=Math.max(0,Math.min(100,+$('score').value));if(!n)return toast('Escribe el nombre del estudiante.');localStorage.setItem('eduquest_'+n,JSON.stringify({name:n,score:s,note:$('note').value,date:new Date().toISOString()}));$('assessmentOut').innerHTML=`<div class="metric"><span>Valoración</span><b>${s}/100</b></div><p>Registro local guardado para ${n}.</p>`}
let currentStudent=null;
const finalQuestions=[
 {q:'¿Cuál es la derivada de una función constante f(x)=7?',o:['0','1','7','x'],a:0,e:'La derivada de toda constante es 0.'},
 {q:'¿Cuál es la derivada de f(x)=x?',o:['0','1','x','x²'],a:1,e:'La función identidad tiene derivada 1.'},
 {q:'Si f(x)=5x−2, entonces f′(x) es:',o:['5','−2','5x','x−2'],a:0,e:'La derivada de mx+b es m.'},
 {q:'La derivada de f(x)=x²−4 es:',o:['x−4','2x','2x−4','x²'],a:1,e:'Por la regla de la potencia, (x²)′=2x.'},
 {q:'Para f(x)=exp(0.3x), la derivada correcta es:',o:['exp(0.3x)','0.3·exp(0.3x)','3·exp(x)','0.3x·exp(0.3x)'],a:1,e:'Se aplica la regla de la cadena.'},
 {q:'La derivada de sin(x) es:',o:['sin(x)','−sin(x)','cos(x)','−cos(x)'],a:2,e:'(sin x)′=cos x.'},
 {q:'La derivada de cos(x) es:',o:['sin(x)','−sin(x)','cos(x)','−cos(x)'],a:1,e:'(cos x)′=−sin x.'},
 {q:'Si f(x)=x²·sin(x), ¿qué regla se aplica principalmente?',o:['Regla de la suma','Regla del producto','Regla del cociente','Regla de la potencia solamente'],a:1,e:'Es un producto de dos funciones.'},
 {q:'Para f(x)=(x²+1)/x, la regla apropiada es:',o:['Producto','Cadena','Cociente','Constante'],a:2,e:'Es el cociente de dos funciones.'},
 {q:'La derivada de (3x+1)^4 es:',o:['4(3x+1)^3','12(3x+1)^3','(3x+1)^3','12(3x+1)^4'],a:1,e:'Cadena: 4(3x+1)^3·3.'},
 {q:'Para x≠0, la derivada de 1/x es:',o:['1/x²','−1/x²','−x²','1'],a:1,e:'1/x=x^−1 y su derivada es −x^−2.'},
 {q:'Para f(x)=|x|, ¿qué ocurre en x=0?',o:['f′(0)=0','f′(0)=1','f′(0)=−1','La derivada no existe'],a:3,e:'Las pendientes laterales son −1 y 1.'},
 {q:'Si f(x)=x²−4, ¿cuánto vale f′(2)?',o:['0','2','4','8'],a:2,e:'f′(x)=2x, por tanto f′(2)=4.'},
 {q:'La recta tangente a f(x)=x² en x₀=2 es:',o:['y=2x+4','y=4x−4','y=4x+4','y=2x−4'],a:1,e:'Pendiente 4 y pasa por (2,4): y−4=4(x−2).'},
 {q:'Si f′(x) cambia de positivo a negativo en un punto crítico, normalmente hay:',o:['Un mínimo local','Un máximo local','Una asíntota','Una constante'],a:1,e:'Crecer→decrecer indica máximo local.'},
 {q:'Si f′(x) cambia de negativo a positivo en un punto crítico, normalmente hay:',o:['Un máximo local','Un mínimo local','Una discontinuidad siempre','Una función constante'],a:1,e:'Decrecer→crecer indica mínimo local.'},
 {q:'Geométricamente, f′(x₀) representa:',o:['La altura de la función','La pendiente de la tangente','El área bajo la curva','El dominio'],a:1,e:'La derivada es la pendiente de la recta tangente.'},
 {q:'En una aplicación de velocidad, si s(t) es posición, entonces s′(t) representa:',o:['Aceleración','Distancia total','Velocidad instantánea','Tiempo'],a:2,e:'La derivada de la posición respecto del tiempo es la velocidad.'},
 {q:'Para hallar candidatos a máximos o mínimos se deben buscar, entre otros:',o:['Solo valores donde f=0','Puntos donde f′=0 o no existe','Solo valores negativos','Solo extremos del dominio'],a:1,e:'Los puntos críticos incluyen f′=0 y puntos donde f′ no existe, si pertenecen al dominio.'},
 {q:'Si una función tiene f′(x)>0 en un intervalo, la función es:',o:['Decreciente','Constante','Creciente','Discontinua'],a:2,e:'Derivada positiva indica crecimiento en el intervalo.'}
];
function showLogin(){$('loginScreen').classList.remove('hide');setTimeout(()=>$('loginName').focus(),80)}
function validEmail(v){return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(v)}
function doLogin(){const n=$('loginName').value.trim().replace(/\s+/g,' '),e=$('loginEmail').value.trim().toLowerCase(),err=$('loginError');if(n.split(' ').length<2){err.textContent='Escribe tu nombre y apellido completos.';err.classList.add('show');return}if(!validEmail(e)){err.textContent='Escribe un correo electrónico válido.';err.classList.add('show');return}err.classList.remove('show');currentStudent={name:n,email:e,loginAt:new Date().toISOString()};$('loginScreen').classList.add('hide');$('studentStatus').textContent='Estudiante: '+n;$('testStatus').textContent='Evaluación final: pendiente';$('studentChip').textContent=n;nav('home');toast('Bienvenido/a, '+n+'.')}
function logout(){currentStudent=null;$('studentStatus').textContent='Estudiante: sin ingreso';$('testStatus').textContent='Evaluación final: pendiente';$('studentChip').textContent='Sin estudiante';showLogin()}
function renderFinalTest(){if(!currentStudent)return showLogin();$('finalIdentity').innerHTML=`<span class="studentBadge">👤 ${currentStudent.name}</span> <span class="studentBadge">✉ ${currentStudent.email}</span><p class="muted" style="margin-bottom:0">La evaluación se asociará a esta identidad. Revisa tus respuestas antes de enviarla.</p>`;const host=$('finalTest');if(host.dataset.ready==='1')return;host.innerHTML=finalQuestions.map((q,i)=>`<article class="testQuestion"><h4>${i+1}. ${q.q}</h4>${q.o.map((op,j)=>`<label class="option"><input type="radio" name="fq${i}" value="${j}"><span>${op}</span></label>`).join('')}</article>`).join('');host.dataset.ready='1'}
function resetFinal(){document.querySelectorAll('#finalTest input[type=radio]').forEach(x=>x.checked=false);$('finalResult').classList.add('hidden')}
function submitFinal(){if(!currentStudent)return showLogin();renderFinalTest();let score=0,unanswered=0,review=[];finalQuestions.forEach((q,i)=>{const picked=document.querySelector(`input[name="fq${i}"]:checked`);if(!picked){unanswered++;review.push(`<li><b>${i+1}.</b> Sin responder. Respuesta correcta: ${q.o[q.a]}.</li>`)}else if(+picked.value===q.a){score+=5;review.push(`<li><b>${i+1}.</b> Correcta ✓</li>`)}else{review.push(`<li><b>${i+1}.</b> Incorrecta. Correcta: ${q.o[q.a]}. ${q.e}</li>`)}});if(unanswered){toast('Responde todas las preguntas antes de enviar la evaluación.');return}const passed=score>=60;const result={student:currentStudent.name,email:currentStudent.email,score,total:100,passed,date:new Date().toISOString()};localStorage.setItem('eduquestFinal_'+currentStudent.email+'_'+Date.now(),JSON.stringify(result));$('testStatus').textContent=`Evaluación final: ${score}/100`;$('finalResult').classList.remove('hidden');$('finalResult').innerHTML=`<div class="scoreBig">${score}/100</div><h3>${passed?'Aprobado':'En proceso de refuerzo'}</h3><p>${passed?'¡Excelente trabajo! Has alcanzado el mínimo de 60 puntos.':'Repasa las reglas y vuelve a estudiar los temas antes de realizar otro intento.'}</p><p class="muted">Estudiante: <b>${currentStudent.name}</b><br>Correo: <b>${currentStudent.email}</b><br>Fecha: ${new Date().toLocaleString('es-CO')}</p><div class="answerReview"><h4>Retroalimentación</h4><ul>${review.join('')}</ul></div><div class="finalActions"><button class="btn" onclick="downloadFinalResult()">Descargar resultado JSON</button><button class="btn secondary" onclick="printFinalResult()">Imprimir resultado</button><button class="btn secondary" onclick="logout()">Cambiar estudiante</button></div>`;toast(`Evaluación final: ${score}/100`);$('finalResult').scrollIntoView({behavior:'smooth',block:'start'})}
function downloadFinalResult(){if(!currentStudent)return;const data={student:currentStudent,report:$('finalResult').innerText,generatedAt:new Date().toISOString()};const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'}));a.download='eduquest-resultado-final.json';a.click()}
function printFinalResult(){const w=window.open('','_blank','noopener');if(!w)return toast('El navegador bloqueó la ventana de impresión.');w.document.write(`<html><head><title>Resultado final - Eduquest</title><style>body{font-family:Arial,sans-serif;padding:30px;color:#09233d}h1{color:#0877c9}.box{border:1px solid #cfe4ee;border-radius:12px;padding:18px}li{margin:7px 0}</style></head><body><h1>Eduquest — Laboratorio de Derivadas</h1><div class="box">${$('finalResult').innerHTML}</div><p>Universidad del Magdalena · Licenciatura en Matemáticas</p></body></html>`);w.document.close();w.focus();w.print()}
function speak(){const txt=document.querySelector('.view.active')?.innerText||'Eduquest Laboratorio de Derivadas';if(!('speechSynthesis'in window))return toast('Narración no disponible.');speechSynthesis.cancel();speechSynthesis.speak(new SpeechSynthesisUtterance(txt.slice(0,3500)))}
function init(){const cover=$('coverImage');cover.src='data:image/png;base64,'+window.EDUQUEST_COVER;$('homeCover').src=cover.src;$('start').onclick=()=>{$('coverScreen').classList.add('hide');showLogin()};$('openCover').onclick=()=>{$('coverScreen').classList.remove('hide')};$('closeCover').onclick=()=>{ $('coverScreen').classList.add('hide'); if(!currentStudent) showLogin(); };$('menu').onclick=()=>$('sidebar').classList.toggle('open');$$('.nav button').forEach(b=>b.onclick=()=>nav(b.dataset.view));$('contrast').onclick=()=>document.body.classList.toggle('high');$('narrate').onclick=speak;$('loginBtn').onclick=doLogin;['loginName','loginEmail'].forEach(id=>$(id).addEventListener('keydown',e=>{if(e.key==='Enter')doLogin()}));$('submitFinal').onclick=submitFinal;$('resetFinal').onclick=resetFinal;$('plot').onclick=plotFunctions;$('csv').onclick=csv;$('functionPNG').onclick=()=>png('functionPlot','eduquest-derivadas');$('save').onclick=projectSave;$('export').onclick=exportProject;$('import').onchange=e=>e.target.files[0]&&importProject(e.target.files[0]);renderRules();renderEx();const p=JSON.parse(localStorage.getItem('eduquestProject')||'null');if(p){[['ptitle','title'],['plevel','level'],['pduration','duration'],['pobjective','objective'],['pchallenge','challenge'],['pevidence','evidence']].forEach(([a,b])=>$(a).value=p[b]||'');renderProject(p)}$('engine').innerHTML='<span class="dot"></span>math.js: listo · Plotly: listo';$('studentStatus').textContent='Estudiante: sin ingreso';$('testStatus').textContent='Evaluación final: pendiente';$('studentChip').textContent='Sin estudiante';showLogin()}
document.addEventListener('DOMContentLoaded',init);